class Solution {
  public int minOperations(int[] nums, int k) {
    long[] even = new long[k], odd = new long[k];
    for (int i = 0; i < nums.length; i++) {
      int rem = nums[i] % k;
      for (int r = 0; r < k; r++) {
        int d = Math.abs(rem - r);
        long cost = Math.min(d, k - d);
        if (i % 2 == 0) even[r] += cost;
        else odd[r] += cost;
      }
    }
    long best = Long.MAX_VALUE;
    for (int x = 0; x < k; x++)
      for (int y = 0; y < k; y++) if (x != y) best = Math.min(best, even[x] + odd[y]);
    return (int) best;
  }
}
